source1_path =  'C:\Users\Administrator\Desktop\MFFW\sourceA\';% 图像文件夹路径source2_path =  'C:\Users\Administrator\Desktop\MFFW\sourceB\';%source3_path =  'F:\A_Matte_MFIFGAN\Evaluation_Index\Evaluation_Index\metric\1\';   source3_path = 'C:\Users\Administrator\Desktop\Text\MFFW\';img_path1_list = dir(strcat(source1_path ,'*.jpg'));img_path2_list = dir(strcat(source2_path ,'*.jpg'));img_path3_list = dir(strcat(source3_path ,'*.png'));%img_path2_list = dir(strcat(source2_path ,'*.bmp'));%img_path3_list = dir(strcat(source3_path ,'*.bmp'));img_num = length(img_path2_list);%获取图像总数量 title = {'Q_NMI','Q_sG','Q_Y(SSIM)','Q_CB','Q_TE(EN)','Q_NCIE','Q_G','Q_SF(空间频率)','Q_P','Q_Piella(Q_S)','Q_C','Q_CV','Q_SCD','Q_ABF','AVG','VIFF','FMI_pixel','FMI_dct','FMI_w','PSNR','MSE'};if img_num > 0 %有满足条件的图像        data=[];        for j = 1:img_num %逐一读取图像              image_name1 = img_path1_list(j).name;% 图像名              image_name2 = img_path2_list(j).name;% 图像名              image_namef = img_path3_list(j).name;            %fprintf(image_name)            I1 =  imread(strcat(source1_path ,image_name1));             I2 =  imread(strcat(source2_path ,image_name2));             F =  imread(strcat(source3_path ,image_namef));             %F=rgb2gray(F);            %图像处理过程              [H,W,D]=size(F);            %fprintf("%d",D);            if D==3                channel=3;                I1=rgb2gray(I1);                I2=rgb2gray(I2);                F=rgb2gray(F);            else                channel=1;            end        I1=double(I1);        I2=double(I2);        F=double(F);        E_index=Index_evaluation2(I1,I2,F);        fprintf('%.4f\n',E_index)        temp=[data;E_index];        data = temp;        end          data = [data;mean(data,1)];        [m,p]=size(data);        data_cell = mat2cell(data,ones(m,1),ones(p,1));        result=[title;data_cell];        %s=xlswrite('F:\Otheer-DL-Method\Desktop\DRPL(DMDN对比)\Lytro\DRPL-Lytro.xlsx',result);        %s=xlswrite('F:\SPATIAL-PYRMID-ATTENTION-FEATURE-FUSION-NETWORK\Deconv_cllapse_down\ASPP_124+124+interp+cov\Lytro_testing_result\results_.xlsx',result);        s=xlswrite('F:\ZMFF\MFI-WHU\End\MFI-WHU.xlsx',result);%保存结果        %dlmwrite('metric_U2Fusion.xlsx',result)end  function res=Index_evaluation2(I1,I2,F)    I1=double(I1);    I2=double(I2);    F=double(F);    Q(1,1)=metricMI(I1,I2,F,1);        %Q_NMI    Q(1,2)=metric_G(I1,I2,F);          %Q_sG    Q(1,3)=metricYang(I1,I2,F);        %Q_SSIM(结构相似性)    Q(1,4)=metricChenBlum(I1,I2,F);    %Q_CB    Q(1,5)=metricMI(I1,I2,F,3);        %Q_TE(交叉熵)    Q(1,6)=metricWang(I1,I2,F);        %Q_NCIE    Q(1,7)=metricXydeas(I1,I2,F);      %Q_G(基于梯度)    Q(1,8)=metricZheng(I1,I2,F);       %Q_SF(Spatial Frequency)    Q(1,9)=metricZhao(I1,I2,F);        %Q_P(相位一致性)    Q(1,10)=metricPeilla(I1,I2,F,1);   %Q_Piella/Q_S    Q(1,11)=metricCvejic(I1,I2,F,2);   %Q_C    Q(1,12)=metricChen(I1,I2,F);       %Q_CV        %Q(1,13)=metricPWW(I1,I2,F);        %Q_M(多尺度分析)    Q(1,13)=analysis_SCD(I1,I2,F);      %Q_SCD(差异相关性总和)    Q(1,14)=analysis_Qabf(I1,I2,F);     %Q_ABF(C.S.Xydeas)    Q(1,15)=metricsAvg_gradient(I1,I2,F);    %AVG(平均梯度)    Q(1,16)=VIFF_Public(I1,I2,F);      %VIFF        Q(1,17)=analysis_fmi(I1,I2,F);          %FMI_pixel    Q(1,18)=analysis_fmi(I1,I2,F,'dct');     %FMI_dct    Q(1,19)=analysis_fmi(I1,I2,F,'wavelet');  %FMI_w    Q(1,20) = PSNR_evaluation(I1, I2, F);    %PSNR    Q(1,21) = MSE_evaluation(I1, I2, F);         %MSE           res=Q;end